function isPortOpen(host: string, port: number, timeoutMs: number): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    const done = (value: boolean) => {
      try {
        socket.destroy();
      } catch {}
      resolve(value);
    };
    socket.setTimeout(timeoutMs);
    socket.once("connect", () => done(true));
    socket.once("timeout", () => done(false));
    socket.once("error", () => done(false));
    socket.connect(port, host);
  });
}

function createEnsureEngineDevServerPlugin(options: { readonly host: string; readonly port: number; readonly repoRootPath: string }) {
  const { host, port, repoRootPath } = options;

  let engineProc: ChildProcessWithoutNullStreams | undefined;
  let starting: Promise<void> | undefined;

  async function ensureStarted(): Promise<void> {
    if (await isPortOpen(host, port, 250)) return;
    if (engineProc) return;
    if (starting) return starting;

    starting = (async () => {
      if (await isPortOpen(host, port, 250)) return;

      // Storybook should be able to execute native algorithms without requiring a separate manual engine process.
      // We intentionally scope this to the Storybook dev server plugin so it does not affect the original engine implementation.
      // eslint-disable-next-line no-console
      console.log(`[DEBUG] semio/algorithms: starting semio engine dev server on ${host}:${port}`);

      engineProc = spawn("uv", ["run", "python", "-c", "import main; main.start_engine()"], {
        cwd: resolve(repoRootPath, "semio/engine"),
        env: {
          ...process.env,
          HOST: "0.0.0.0",
          PORT: String(port),
        },
        stdio: "pipe",
      });

      engineProc.stdout.on("data", (buf) => {
        // eslint-disable-next-line no-console
        console.log(String(buf).trimEnd());
      });
      engineProc.stderr.on("data", (buf) => {
        // eslint-disable-next-line no-console
        console.error(String(buf).trimEnd());
      });
      engineProc.on("exit", (code, signal) => {
        // eslint-disable-next-line no-console
        console.log(`[DEBUG] semio/algorithms: engine dev server exited (code=${code}, signal=${signal})`);
        engineProc = undefined;
        starting = undefined;
      });

      // Wait for port to become available (best-effort).
      const deadlineMs = Date.now() + 20_000;
      while (Date.now() < deadlineMs) {
        if (await isPortOpen(host, port, 250)) return;
        await new Promise((r) => setTimeout(r, 250));
      }
    })();

    try {
      await starting;
    } finally {
      starting = undefined;
    }
  }

  return {
    name: "semio:ensure-engine-dev-server",
    apply: "serve",
    async configureServer(server: any) {
      await ensureStarted();
      server.httpServer?.once?.("close", () => {
        if (!engineProc) return;
        // eslint-disable-next-line no-console
        console.log("[DEBUG] semio/algorithms: stopping engine dev server");
        try {
          engineProc.kill("SIGTERM");
        } catch {}
        engineProc = undefined;
      });
    },
  };
}

function getAbsolutePath(value: string): string {
  try {
    return dirname(require.resolve(join(value, "package.json")));
  } catch {
    return dirname(require.resolve(join("../../../elements/ui/node_modules", value, "package.json")));
  }
}

